css:
.print-format .afm-chq,
.print-format .afm-chq div,
.print-format .afm-chq td,
.print-format .afm-chq p,
.print-format .afm-chq label,
.print-format .afm-chq span,
.print-format .afm-chq strong,
.print-format .afm-chq h4 {
  font-family: "Noto Sans Arabic", "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format .afm-chq .en,
.print-format .afm-chq .num,
.print-format .afm-chq .ltr {
  font-family: "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format .afm-chq { color: #171717; font-size: 8.5pt; line-height: 14px; -webkit-print-color-adjust: exact; }
.afm-chq b, .afm-chq strong { font-weight: bold; }
.afm-chq .num { white-space: nowrap; direction: ltr; unicode-bidi: embed; }
.afm-chq .ltr { direction: ltr; unicode-bidi: embed; }


.afm-chq table { width: 100%; border-collapse: collapse; table-layout: fixed; border-spacing: 0; }
.print-format .afm-chq table td { padding: 0 !important; vertical-align: middle !important; border: 0; }
.afm-chq .afm-chq-hdr .logo img { height: 48px; width: auto; display: block; }
.afm-chq .ids td { font-size: 8.5pt; line-height: 14px; white-space: nowrap; vertical-align: baseline !important; }
.afm-chq .ids td.ctr { text-align: center; }
.afm-chq .ids .k { font-size: 7pt; color: #5f5f5f; }
.afm-chq .ids .k.ltr { font-size: 6pt; text-align: left; }
.afm-chq .afm-chq-rule { margin: 0 0 8px 0; }
.print-format .afm-chq .afm-chq-rule td { height: 8px; }
.afm-chq .afm-chq-rule .thin { border-bottom: 0.75pt solid #00844e; }
.afm-chq .afm-chq-rule .thick { border-bottom: 2.4pt solid #00844e; }


.afm-chq .afm-chq-title { margin: 0 0 8px 0; border-bottom: 1.2pt solid #00844e; }
.print-format .afm-chq .afm-chq-title td { padding: 0 0 4px 0 !important; vertical-align: bottom !important; }
.afm-chq .afm-chq-title .t-ar { font-size: 13pt; line-height: 20px; font-weight: bold; display: block; white-space: nowrap; color: #171717; }
.afm-chq .afm-chq-title .t-en { font-size: 8.5pt; line-height: 14px; color: #5f5f5f; direction: ltr; unicode-bidi: embed; display: block; white-space: nowrap; text-align: right; }
.afm-chq .afm-chq-title td.docno { text-align: left; }
.afm-chq .afm-chq-title .docno .num { font-size: 8.5pt; line-height: 14px; font-weight: bold; color: #171717; }
.print-format .afm-chq .afm-chq-status h4 { margin: 0; font-size: 8.5pt; line-height: 14px; font-weight: bold; color: #5f5f5f; }


.print-format .afm-chq label { font-weight: normal; color: #5f5f5f; white-space: nowrap; }
.afm-chq .ar { font-size: 7pt; line-height: 12px; color: #5f5f5f; font-weight: normal; white-space: nowrap; }
.afm-chq .en { font-size: 6pt; line-height: 10px; color: #5f5f5f; font-weight: normal; white-space: nowrap; direction: ltr; unicode-bidi: embed; padding: 0 4px 0 0; }
.afm-chq .en.solo { font-size: 7pt; line-height: 12px; padding: 0; }
.afm-chq .v { color: #171717; font-size: 8.5pt; line-height: 14px; }
.afm-chq .v strong { font-weight: bold; }
.print-format .afm-chq p.lead-line { margin: 0 0 4px 0; padding: 0 4px 0 0; text-align: right; }
.afm-chq p.lead-line .ar, .afm-chq p.lead-line .en { white-space: normal; }
.print-format .afm-chq hr { border: 0; border-top: 0.75pt solid #d0d0d0; }


.afm-chq .sig { white-space: nowrap; }

.print-format .afm-chq .chq, .print-format .afm-chq .chq strong { font-family: "DejaVu Sans", sans-serif !important; font-size: 9pt; line-height: 1.42857143; color: #171717; }

.print-format .afm-chq.page-break { page-break-after: auto !important; }

html:
{%- macro lbl(key, en) -%}
{%- set _a = _(key, lang='ar') -%}
{%- if _a and _a != key %}<span class="ar">{{ _a }}</span><span class="en">{{ en }}</span>{% else %}<span class="en solo">{{ en }}</span>{% endif -%}
{%- endmacro -%}

{%- set _afm_co = frappe.db.get_value('Company', doc.company, ['tax_id', 'company_logo'], as_dict=1) or {} -%}
{%- set _afm_zbs = frappe.db.get_value('ZATCA Business Settings', {'company': doc.company}, 'name') if doc.company else none -%}
{%- set _afm_ns = namespace(cr='') -%}
{%- if _afm_zbs -%}
  {%- for r in frappe.get_doc('ZATCA Business Settings', _afm_zbs).other_ids -%}{%- if r.type_code == 'CRN' and r.value and not _afm_ns.cr -%}{%- set _afm_ns.cr = r.value -%}{%- endif -%}{%- endfor -%}
{%- endif -%}
{%- set _afm_logo = _afm_co.company_logo or '/files/afmco-logo-full-1200w.png' -%}
{%- set _t_ar = _('Payment Advice', lang='ar') -%}
<div style="position: relative">
<div class="page-break afm-chq">
  <table class="afm-chq-hdr">
    <colgroup><col style="width:30mm"><col><col style="width:66mm"></colgroup>
    <tr>
      <td class="logo"><img src="{{ _afm_logo }}" alt="AFMCO"></td>
      <td></td>
      <td>
        <table class="ids">
          <colgroup><col style="width:24mm"><col><col style="width:14mm"></colgroup>
          {%- if _afm_co.tax_id %}
          {%- set _k = _('Tax Id', lang='ar') %}
          <tr><td class="k">{{ _k if _k != 'Tax Id' else '' }}</td><td class="num ctr"><b>{{ _afm_co.tax_id }}</b></td><td class="k ltr">VAT No.</td></tr>
          {%- endif %}
          {%- if _afm_ns.cr %}
          {%- set _k = _('Commercial Registration Number', lang='ar') %}
          <tr><td class="k">{{ _k if _k != 'Commercial Registration Number' else '' }}</td><td class="num ctr"><b>{{ _afm_ns.cr }}</b></td><td class="k ltr">CR No.</td></tr>
          {%- endif %}
        </table>
      </td>
    </tr>
  </table>
  <table class="afm-chq-rule"><colgroup><col style="width:22%"><col></colgroup><tr><td class="thick"></td><td class="thin"></td></tr></table>
  <table class="afm-chq-title">
    <tr>
      <td>
        {%- if _t_ar and _t_ar != 'Payment Advice' %}<span class="t-ar">{{ _t_ar }}</span><span class="t-en">Payment Advice</span>
        {%- else %}<span class="t-ar ltr">Payment Advice</span>{% endif -%}
      </td>
      <td class="docno"><span class="num">{{ doc.name }}</span></td>
    </tr>
  </table>
  {%- if doc.docstatus == 0 %}<div class="text-center afm-chq-status" document-status="draft"><h4>{{ _("DRAFT") }}</h4></div>{% endif -%}
  {%- if doc.docstatus == 2 %}<div class="text-center afm-chq-status" document-status="cancelled"><h4>{{ _("CANCELLED") }}</h4></div>{% endif -%}

{%- for key, en, value in (
        ("Voucher Date", "Voucher Date", frappe.utils.formatdate(doc.get("voucher_date") or doc.posting_date)),
        ("Reference / Cheque No.", "Reference / Cheque No.", doc.cheque_no or ""),
        ("Reference / Cheque Date", "Reference / Cheque Date", frappe.utils.formatdate(doc.cheque_date) if doc.cheque_date else "")
    ) -%}
    <div class="row">
        <div class="col-xs-4"><label class="text-right">{{ lbl(key, en) }}</label></div>
        <div class="col-xs-8 v">{{ value }}</div>
    </div>
{%- endfor -%}
	<hr>
	<p class="lead-line">{{ lbl("This amount is in full / part settlement of the listed bills", "This amount is in full / part settlement of the listed bills:") }}</p>
{%- for key, en, value in (
        ("Amount", "Amount", "<strong>" + doc.get_formatted("total_amount") + "</strong><br>" + (doc.total_amount_in_words or "") + "<br>"),
        ("References", "References", doc.remark or "")
    ) -%}
    <div class="row">
        <div class="col-xs-4"><label class="text-right">{{ lbl(key, en) }}</label></div>
        <div class="col-xs-8 v">{{ value }}</div>
    </div>
    {%- endfor -%}
    <hr>
	<div class="sig" style="position: absolute; top: 14cm; left: 0cm;">
		{{ lbl("Prepared By", "Prepared By") }}</div>
	<div class="sig" style="position: absolute; top: 14cm; left: 5.5cm;">
		{{ lbl("Authorised Signatory", "Authorised Signatory") }}</div>
	<div class="sig" style="position: absolute; top: 14cm; left: 11cm;">
		{{ lbl("Received Payment as Above", "Received Payment as Above") }}</div>
	<div class="chq" style="position: absolute; top: 16.4cm; left: 5.9cm;">
		<strong>_____________</strong></div>
	<div class="chq" style="position: absolute; top: 16.7cm; left: 6cm;">
		<strong>A/C Payee</strong></div>
	<div class="chq" style="position: absolute; top: 16.7cm; left: 5.9cm;">
		<strong>_____________</strong></div>
	<div class="chq" style="position: absolute; top: 16.9cm; left: 12cm;">
		{{ frappe.utils.formatdate(doc.cheque_date) if doc.cheque_date else "" }}</div>
	<div class="chq" style="position: absolute; top: 17.9cm; left: 1cm;">
		{{ doc.pay_to_recd_from or "" }}</div>
	<div class="chq" style="position: absolute; top: 18.6cm; left: 1cm; width: 7cm;">
		{{ doc.total_amount_in_words or "" }}</div>
	<div class="chq" style="position: absolute; top: 19.7cm; left: 12cm;">
		{{ doc.get_formatted("total_amount") }}</div>
</div>
